css:
/* Read channels and DMs recede; unread, mentions and the open one stay bright */
.p-channel_sidebar__channel:not(.p-channel_sidebar__channel--unread):not(.p-channel_sidebar__channel--selected) {
  opacity: .45;
  transition: opacity .15s;
}
.p-channel_sidebar__channel--muted:not(.p-channel_sidebar__channel--selected) {
  opacity: .25;
}
.p-channel_sidebar__list:hover .p-channel_sidebar__channel {
  opacity: 1;
}
.p-channel_sidebar__channel--unread .p-channel_sidebar__name {
  font-weight: 800;
}
